// Normaliza el payload de WhatsApp Cloud API a { telefono, nombre, texto }.
// El trigger nativo entrega el objeto `value` de Meta; si alguien reemplaza
// el trigger por un webhook genérico, el payload llega bajo .body.
const j = $json;
const value = j.body?.entry?.[0]?.changes?.[0]?.value ?? j.entry?.[0]?.changes?.[0]?.value ?? j;

const message = value.messages?.[0] ?? {};
const contact = value.contacts?.[0] ?? {};

const telefono = message.from ?? contact.wa_id ?? '';
const nombre = contact.profile?.name ?? null;

// Solo procesamos texto. Audio/imagen/documento se marcan para que el
// agente pida al cliente que escriba, en vez de romper el flujo.
const tipo = message.type ?? 'desconocido';
const texto = tipo === 'text'
  ? (message.text?.body ?? '')
  : `[El cliente envió un mensaje de tipo "${tipo}" que no puedo leer]`;

return {
  json: {
    telefono,
    nombre,
    texto,
    tipo,
    es_texto: tipo === 'text',
    wa_message_id: message.id ?? null
  }
};
